rules:
@layer utilities {
  .\@container\/card-header { container: card-header / inline-size; }
  .\@container\/field-group { container: field-group / inline-size; }
  .pointer-events-auto { pointer-events: auto; }
  .pointer-events-none { pointer-events: none; }
  .collapse { visibility: collapse; }
  .invisible { visibility: hidden; }
  .visible { visibility: visible; }
  .sr-only { clip-path: inset(50%); white-space: nowrap; border-width: 0px; width: 1px; height: 1px; margin: -1px; padding: 0px; position: absolute; overflow: hidden; }
  .absolute { position: absolute; }
  .fixed { position: fixed; }
  .relative { position: relative; }
  .static { position: static; }
  .sticky { position: sticky;

@keyframes pin-glow { 
  0%, 100% { box-shadow: 0 2px 8px oklch(from var(--cmstdev) l c h / 35%); }
  50% { box-shadow: 0 2px 16px oklch(from var(--cmstdev) l c h / 60%); }
}

@supports (color:color-mix(in lab, red, red)) {
  .qr-scan-band { background: linear-gradient(to bottom, transparent, color-mix(in srgb, var(--cmstdev) 32%, transparent)); }
}

